  if(!stream)return send(completed);res.writeHead(200,{'content-type':'text/event-stream'});let n=0;const emit=(type,value)=>event(type,{type,sequence_number:n++,...value});emit('response.created',{response:{...completed,status:'in_progress',output:[]}});emit('response.output_item.added',{output_index:0,item:tool?{...item,arguments:'',status:'in_progress'}:{...item,content:[],status:'in_progress'}});if(tool){emit('response.function_call_arguments.delta',{item_id:item.id,output_index:0,delta:item.arguments});emit('response.function_call_arguments.done',{item_id:item.id,output_index:0,arguments:item.arguments});}else{emit('response.content_part.added',{item_id:item.id,output_index:0,content_index:0,part:{type:'output_text',text:'',annotations:[]}});emit('response.output_text.delta',{item_id:item.id,output_index:0,content_index:0,delta:TEXT});emit('response.output_text.done',{item_id:item.id,output_index:0,content_index:0,text:TEXT});emit('response.content_part.done',{item_id:item.id,output_index:0,content_index:0,part:item.content[0]});}emit('response.output_item.done',{output_index:0,item});emit('response.completed',{response:completed});return res.end();
